export const I18N_TRANSLATIONS: Record<UiLang, Dict> = Object.fromEntries(
  Object.entries(I18N_TRANSLATION_OVERRIDES).map(([lang, messages]) => [
    lang,
    {
      ...messages,
      ...(I18N_TRANSLATION_COMPLETIONS[lang as UiLang] ?? {}),
    },
  ]),
) as Record<UiLang, Dict>;

export const I18N_CATALOG: Record<UiLang, Dict> = Object.fromEntries(
  Object.entries(I18N_TRANSLATIONS).map(([lang, messages]) => [
    lang,
    { ...EN_MESSAGES, ...messages },
  ]),
) as Record<UiLang, Dict>;
